Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="btnSweep">Animate marginalization over z</button>
<label>
  latent variable z
  <input id="latentZ" type="range" min="-2.5" max="2.5" step="0.05" value="0">
