<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// joint-space cuboid → 12 brown CylinderGeometry edges
// conditional slice planes → three dark reddish-brown PlaneGeometry rectangles at fixed z
// conditional density glows → CanvasTexture heatmaps on transparent PlaneGeometry overlays
// nonlinear decoder mean → cyan TubeGeometry curve through (x1,x2,z)
// hidden trajectory portion → dashed cyan Line through central z interval
// trajectory sample points → teal SphereGeometry markers with pale outline spheres
// trajectory arrowhead → cyan ConeGeometry aligned to curve tangent
// current-z slice indicator → translucent cyan PlaneGeometry plus cyan rectangular border
// current conditional glow → dynamic CanvasTexture on current-z slice
// z-axis marker → small teal SphereGeometry on lower-front z axis
// posterior Pr(z|x,phi) ridge → weighted glowing teal/cream spheres along z axis
// marginal panel → right-side PlaneGeometry with dynamic marginal CanvasTexture
// marginal panel border → black LineLoop rectangle
// projected marginal curve → cyan TubeGeometry on right x1-x2 panel
// marginal sample points / draggable observation → teal SphereGeometry markers on panel
// marginal curve arrowhead → cyan ConeGeometry on panel curve tangent
// marginalization sweep plane → translucent cyan-white PlaneGeometry moving along z
// projection trace line → pale cyan Line from selected slice mean toward right panel point
// large marginalization arrow → pale gray cylinder shaft plus ConeGeometry head
// all visible math/caption text → addLabel HTML labels

const brown = 0x7a351e;
const darkBrown = 0x2a0702;
const cyan = 0x9be0dc;
const teal = 0x2d8f8a;
const cream = 0xfff0bf;
const paleGray = 0xc8cfd0;

scene.add(new THREE.AmbientLight(0xffffff, 1));

const xMin = -2.5, xMax = 2.5;
const yMin = -2.0, yMax = 2.0;
const zMin = -2.5, zMax = 2.5;
const rightPanel = {
  cx: 5.45,
  cy: -0.12,
  z: -0.55,
  w: 2.2,
  h: 3.2,
  xRange: [-2.5, 2.5],
  yRange: [-2.0, 2.0]
};

function mu(z) {
  return {
    x: 1.35 * Math.sin(1.15 * z) + 0.35 * z,
    y: -0.55 * z + 1.1 * Math.cos(z)
  };
}

function prior(z) {
  return Math.exp(-0.5 * z * z);
}

function gaussian2D(x, y, z) {
  const m = mu(z);
  const a = 0.85 * z;
  const c = Math.cos(a), s = Math.sin(a);
  const dx = x - m.x, dy = y - m.y;
  const u = c * dx + s * dy;
  const v = -s * dx + c * dy;
  const s1 = 0.35, s2 = 0.8;
  return Math.exp(-0.5 * ((u * u) / (s1 * s1) + (v * v) / (s2 * s2)));
}

function lerp(a, b, t) { return a + (b - a) * t; }
function colorRamp(t) {
  t = Math.max(0, Math.min(1, t));
  let c0, c1, u;
  if (t < 0.45) {
    c0 = [37, 6, 2]; c1 = [183, 90, 58]; u = t / 0.45;
  } else {
    c0 = [183, 90, 58]; c1 = [255, 240, 191]; u = (t - 0.45) / 0.55;
  }
  return [
    Math.round(lerp(c0[0], c1[0], u)),
    Math.round(lerp(c0[1], c1[1], u)),
    Math.round(lerp(c0[2], c1[2], u))
  ];
}

function makeConditionalTexture(z, opts = {}) {
  const size = opts.size || 160;
  const canvasTex = document.createElement('canvas');
  canvasTex.width = size;
  canvasTex.height = size;
  const ctx = canvasTex.getContext('2d');
  const img = ctx.createImageData(size, size);
  const data = img.data;
  for (let j = 0; j < size; j++) {
    const y = yMax - (j / (size - 1)) * (yMax - yMin);
    for (let i = 0; i < size; i++) {
      const x = xMin + (i / (size - 1)) * (xMax - xMin);
      const v = gaussian2D(x, y, z) * (opts.usePrior ? prior(z) : 1);
      const t = Math.pow(Math.min(1, v), 0.52);
      const col = colorRamp(t);
      const k = 4 * (j * size + i);
      data[k] = col[0];
      data[k + 1] = col[1];
      data[k + 2] = col[2];
      data[k + 3] = Math.round(245 * Math.pow(t, 1.15));
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvasTex);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function redrawConditionalTexture(tex, z) {
  const canvasTex = tex.image;
  const size = canvasTex.width;
  const ctx = canvasTex.getContext('2d');
  const img = ctx.createImageData(size, size);
  const data = img.data;
  for (let j = 0; j < size; j++) {
    const y = yMax - (j / (size - 1)) * (yMax - yMin);
    for (let i = 0; i < size; i++) {
      const x = xMin + (i / (size - 1)) * (xMax - xMin);
      const v = gaussian2D(x, y, z) * prior(z);
      const t = Math.pow(Math.min(1, v), 0.50);
      const col = colorRamp(t);
      const k = 4 * (j * size + i);
      data[k] = col[0];
      data[k + 1] = col[1];
      data[k + 2] = col[2];
      data[k + 3] = Math.round(250 * Math.pow(t, 1.1));
    }
  }
  ctx.putImageData(img, 0, 0);
  tex.needsUpdate = true;
}

function cylinderBetween(a, b, r, color, opacity = 1) {
  const mid = new THREE.Vector3().addVectors(a, b).multiplyScalar(0.5);
  const len = a.distanceTo(b);
  const geom = new THREE.CylinderGeometry(r, r, len, 10);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), new THREE.Vector3().subVectors(b, a).normalize());
  scene.add(mesh);
  return mesh;
}

function makeConeAt(pos, dir, radius, height, color, opacity = 1) {
  const geom = new THREE.ConeGeometry(radius, height, 24);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, depthWrite: opacity >= 1 });
  const cone = new THREE.Mesh(geom, mat);
  cone.position.copy(pos);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  scene.add(cone);
  return cone;
}

function lineLoop(points, color, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints([...points, points[0]]);
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const line = new THREE.Line(geom, mat);
  scene.add(line);
  return line;
}

const corners = [];
for (const x of [xMin, xMax]) for (const y of [yMin, yMax]) for (const z of [zMin, zMax]) corners.push(new THREE.Vector3(x, y, z));
const edgePairs = [
  [[xMin, yMin, zMin], [xMax, yMin, zMin]], [[xMin, yMax, zMin], [xMax, yMax, zMin]],
  [[xMin, yMin, zMax], [xMax, yMin, zMax]], [[xMin, yMax, zMax], [xMax, yMax, zMax]],
  [[xMin, yMin, zMin], [xMin, yMax, zMin]], [[xMax, yMin, zMin], [xMax, yMax, zMin]],
  [[xMin, yMin, zMax], [xMin, yMax, zMax]], [[xMax, yMin, zMax], [xMax, yMax, zMax]],
  [[xMin, yMin, zMin], [xMin, yMin, zMax]], [[xMax, yMin, zMin], [xMax, yMin, zMax]],
  [[xMin, yMax, zMin], [xMin, yMax, zMax]], [[xMax, yMax, zMin], [xMax, yMax, zMax]]
];
edgePairs.forEach(([a, b]) => cylinderBetween(new THREE.Vector3(...a), new THREE.Vector3(...b), 0.015, brown));

const sliceGroup = new THREE.Group();
scene.add(sliceGroup);

function addSlicePlane(z, opacity = 0.9) {
  const base = new THREE.Mesh(
    new THREE.PlaneGeometry(xMax - xMin, yMax - yMin),
    new THREE.MeshBasicMaterial({ color: darkBrown, transparent: true, opacity, side: THREE.DoubleSide, depthWrite: true })
  );
  base.position.set(0, 0, z);
  sliceGroup.add(base);
  const glow = new THREE.Mesh(
    new THREE.PlaneGeometry(xMax - xMin, yMax - yMin),
    new THREE.MeshBasicMaterial({ map: makeConditionalTexture(z, { usePrior: true }), transparent: true, side: THREE.DoubleSide, depthWrite: false })
  );
  glow.position.set(0, 0, z + 0.012);
  glow.renderOrder = 4;
  sliceGroup.add(glow);
  const borderPts = [
    new THREE.Vector3(xMin, yMin, z + 0.018),
    new THREE.Vector3(xMax, yMin, z + 0.018),
    new THREE.Vector3(xMax, yMax, z + 0.018),
    new THREE.Vector3(xMin, yMax, z + 0.018)
  ];
  const border = lineLoop(borderPts, brown, 0.9);
  sliceGroup.add(border);
  return { base, glow, border };
}
[-1.8, 0.0, 1.4].forEach(z => addSlicePlane(z));

function curvePoint(z) {
  const m = mu(z);
  return new THREE.Vector3(m.x, m.y, z);
}

function makeTubeForZRange(a, b, color, radius = 0.035) {
  const pts = [];
  const n = 80;
  for (let i = 0; i < n; i++) {
    const z = a + (b - a) * i / (n - 1);
    pts.push(curvePoint(z));
  }
  const curve = new THREE.CatmullRomCurve3(pts);
  const geom = new THREE.TubeGeometry(curve, 120, radius, 12, false);
  const mat = new THREE.MeshBasicMaterial({ color });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.renderOrder = 8;
  scene.add(mesh);
  return mesh;
}
makeTubeForZRange(-2.35, -0.38, cyan);
makeTubeForZRange(0.48, 2.22, cyan);

const dashedPts = [];
for (let i = 0; i < 50; i++) dashedPts.push(curvePoint(-0.38 + 0.86 * i / 49));
const dashedLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(dashedPts),
  new THREE.LineDashedMaterial({ color: cyan, dashSize: 0.14, gapSize: 0.10, transparent: true, opacity: 0.95 })
);
dashedLine.computeLineDistances();
dashedLine.renderOrder = 9;
scene.add(dashedLine);

const endZ = 2.22;
const endP = curvePoint(endZ);
const tangent = curvePoint(endZ).sub(curvePoint(endZ - 0.08)).normalize();
makeConeAt(endP.clone().add(tangent.clone().multiplyScalar(0.12)), tangent, 0.13, 0.33, cyan, 0.9);

function addTealSphere(pos, r = 0.08) {
  const outer = new THREE.Mesh(
    new THREE.SphereGeometry(r * 1.33, 24, 16),
    new THREE.MeshBasicMaterial({ color: cyan, transparent: true, opacity: 0.65 })
  );
  outer.position.copy(pos);
  scene.add(outer);
  const inner = new THREE.Mesh(
    new THREE.SphereGeometry(r, 24, 16),
    new THREE.MeshBasicMaterial({ color: teal })
  );
  inner.position.copy(pos);
  scene.add(inner);
  return inner;
}
addTealSphere(curvePoint(-1.8), 0.085);
addTealSphere(curvePoint(1.25), 0.085);

const currentSliceTex = makeConditionalTexture(0, { usePrior: true, size: 160 });
const currentSlice = new THREE.Mesh(
  new THREE.PlaneGeometry(xMax - xMin, yMax - yMin),
  new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false })
);
currentSlice.position.set(0, 0, 0.02);
currentSlice.renderOrder = 10;
scene.add(currentSlice);

const currentGlow = new THREE.Mesh(
  new THREE.PlaneGeometry(xMax - xMin, yMax - yMin),
  new THREE.MeshBasicMaterial({ map: currentSliceTex, transparent: true, side: THREE.DoubleSide, opacity: 0.85, depthWrite: false })
);
currentGlow.position.set(0, 0, 0.035);
currentGlow.renderOrder = 11;
scene.add(currentGlow);

let currentBorder = null;
function makeCurrentBorder(z) {
  if (currentBorder) scene.remove(currentBorder);
  currentBorder = lineLoop([
    new THREE.Vector3(xMin, yMin, z + 0.055),
    new THREE.Vector3(xMax, yMin, z + 0.055),
    new THREE.Vector3(xMax, yMax, z + 0.055),
    new THREE.Vector3(xMin, yMax, z + 0.055)
  ], cyan, 0.95);
  currentBorder.renderOrder = 12;
}
makeCurrentBorder(0);

const zAxisMarker = addTealSphere(new THREE.Vector3(xMin, yMin, 0), 0.075);

const posteriorGroup = new THREE.Group();
scene.add(posteriorGroup);
const posteriorDots = [];
for (let i = 0; i < 70; i++) {
  const mat = new THREE.MeshBasicMaterial({ color: cream, transparent: true, opacity: 0.1, depthWrite: false });
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.045, 16, 10), mat);
  dot.position.set(xMin + 0.16, yMin + 0.18, zMin + (zMax - zMin) * i / 69);
  posteriorGroup.add(dot);
  posteriorDots.push(dot);
}

const marginalW = 112, marginalH = 160, zSamples = 121;
const zGrid = [];
for (let k = 0; k < zSamples; k++) zGrid.push(zMin + (zMax - zMin) * k / (zSamples - 1));
const marginalSlices = [];
const fullMarginal = new Float32Array(marginalW * marginalH);
let marginalMax = 0;
for (let k = 0; k < zSamples; k++) {
  const z = zGrid[k];
  const arr = new Float32Array(marginalW * marginalH);
  for (let j = 0; j < marginalH; j++) {
    const y = rightPanel.yRange[1] - (j / (marginalH - 1)) * (rightPanel.yRange[1] - rightPanel.yRange[0]);
    for (let i = 0; i < marginalW; i++) {
      const x = rightPanel.xRange[0] + (i / (marginalW - 1)) * (rightPanel.xRange[1] - rightPanel.xRange[0]);
      const val = gaussian2D(x, y, z) * prior(z);
      const idx = j * marginalW + i;
      arr[idx] = val;
      fullMarginal[idx] += val;
    }
  }
  marginalSlices.push(arr);
}
for (let i = 0; i < fullMarginal.length; i++) marginalMax = Math.max(marginalMax, fullMarginal[i]);

const marginalCanvas = document.createElement('canvas');
marginalCanvas.width = marginalW;
marginalCanvas.height = marginalH;
const marginalCtx = marginalCanvas.getContext('2d');
const marginalTex = new THREE.CanvasTexture(marginalCanvas);
marginalTex.colorSpace = THREE.SRGBColorSpace;

function drawMarginalTexture(progress = 1) {
  const img = marginalCtx.createImageData(marginalW, marginalH);
  const data = img.data;
  const upto = Math.max(1, Math.floor(progress * zSamples));
  for (let idx = 0; idx < marginalW * marginalH; idx++) {
    let sum = 0;
    for (let k = 0; k < upto; k++) sum += marginalSlices[k][idx];
    const t = Math.pow(Math.min(1, sum / marginalMax), 0.46);
    const col = colorRamp(t);
    const base = 4 * idx;
    data[base] = col[0];
    data[base + 1] = col[1];
    data[base + 2] = col[2];
    data[base + 3] = 255;
  }
  marginalCtx.putImageData(img, 0, 0);
  marginalTex.needsUpdate = true;
}
drawMarginalTexture(1);

const panelMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(rightPanel.w, rightPanel.h),
  new THREE.MeshBasicMaterial({ map: marginalTex, side: THREE.DoubleSide })
);
panelMesh.position.set(rightPanel.cx, rightPanel.cy, rightPanel.z);
panelMesh.renderOrder = 1;
scene.add(panelMesh);
registerInteractive(panelMesh, {
  title: 'Marginal density Pr(x | φ)',
  body: 'This panel shows the observable density after integrating all latent-z conditional slices.',
  tooltip: 'Drag the teal observation point here'
});

function panelWorldFromData(x, y, zoff = 0.035) {
  const lx = (x - rightPanel.xRange[0]) / (rightPanel.xRange[1] - rightPanel.xRange[0]) * rightPanel.w - rightPanel.w / 2;
  const ly = (y - rightPanel.yRange[0]) / (rightPanel.yRange[1] - rightPanel.yRange[0]) * rightPanel.h - rightPanel.h / 2;
  return new THREE.Vector3(rightPanel.cx + lx, rightPanel.cy + ly, rightPanel.z + zoff);
}
function dataFromPanelLocal(local) {
  return {
    x: rightPanel.xRange[0] + ((local.x + rightPanel.w / 2) / rightPanel.w) * (rightPanel.xRange[1] - rightPanel.xRange[0]),
    y: rightPanel.yRange[0] + ((local.y + rightPanel.h / 2) / rightPanel.h) * (rightPanel.yRange[1] - rightPanel.yRange[0])
  };
}

const borderZ = rightPanel.z + 0.045;
lineLoop([
  new THREE.Vector3(rightPanel.cx - rightPanel.w / 2, rightPanel.cy - rightPanel.h / 2, borderZ),
  new THREE.Vector3(rightPanel.cx + rightPanel.w / 2, rightPanel.cy - rightPanel.h / 2, borderZ),
  new THREE.Vector3(rightPanel.cx + rightPanel.w / 2, rightPanel.cy + rightPanel.h / 2, borderZ),
  new THREE.Vector3(rightPanel.cx - rightPanel.w / 2, rightPanel.cy + rightPanel.h / 2, borderZ)
], 0x000000, 1);

const panelCurvePts = [];
for (let i = 0; i < 120; i++) {
  const z = -2.35 + (2.22 + 2.35) * i / 119;
  const m = mu(z);
  panelCurvePts.push(panelWorldFromData(m.x, Math.max(rightPanel.yRange[0] + 0.02, Math.min(rightPanel.yRange[1] - 0.02, m.y)), 0.075));
}
const panelCurve = new THREE.CatmullRomCurve3(panelCurvePts);
const panelCurveMesh = new THREE.Mesh(
  new THREE.TubeGeometry(panelCurve, 150, 0.018, 8, false),
  new THREE.MeshBasicMaterial({ color: cyan, transparent: true, opacity: 0.92 })
);
panelCurveMesh.renderOrder = 8;
scene.add(panelCurveMesh);

const panelEnd = panelCurvePts[panelCurvePts.length - 1];
const panelTan = panelEnd.clone().sub(panelCurvePts[panelCurvePts.length - 5]).normalize();
