  const s1 = 0.35, s2 = 0.8;
  return Math.exp(-0.5 * ((u * u) / (s1 * s1) + (v * v) / (s2 * s2)));
}

function lerp(a, b, t) { return a + (b - a) * t; }
function colorRamp(t) {
  t = Math.max(0, Math.min(1, t));
  let c0, c1, u;
  if (t < 0.45) {
    c0 = [37, 6, 2]; c1 = [183, 90, 58]; u = t / 0.45;
  } else {
    c0 = [183, 90, 58]; c1 = [255, 240, 191]; u = (t - 0.45) / 0.55;
  }
  return [
    Math.round(lerp(c0[0], c1[0], u)),
    Math.round(lerp(c0[1], c1[1], u)),
    Math.round(lerp(c0[2], c1[2], u))
  ];
}

function makeConditionalTexture(z, opts = {}) {
  const size = opts.size || 160;
  const canvasTex = document.createElement('canvas');
  canvasTex.width = size;
  canvasTex.height = size;
  const ctx = canvasTex.getContext('2d');
  const img = ctx.createImageData(size, size);
  const data = img.data;
  for (let j = 0; j < size; j++) {
    const y = yMax - (j / (size - 1)) * (yMax - yMin);
    for (let i = 0; i < size; i++) {
      const x = xMin + (i / (size - 1)) * (xMax - xMin);
      const v = gaussian2D(x, y, z) * (opts.usePrior ? prior(z) : 1);
      const t = Math.pow(Math.min(1, v), 0.52);
      const col = colorRamp(t);
      const k = 4 * (j * size + i);
      data[k] = col[0];
      data[k + 1] = col[1];
      data[k + 2] = col[2];
      data[k + 3] = Math.round(245 * Math.pow(t, 1.15));
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvasTex);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function redrawConditionalTexture(tex, z) {
  const canvasTex = tex.image;
  const size = canvasTex.width;
  const ctx = canvasTex.getContext('2d');
  const img = ctx.createImageData(size, size);
  const data = img.data;
  for (let j = 0; j < size; j++) {
    const y = yMax - (j / (size - 1)) * (yMax - yMin);
    for (let i = 0; i < size; i++) {
      const x = xMin + (i / (size - 1)) * (xMax - xMin);
      const v = gaussian2D(x, y, z) * prior(z);
      const t = Math.pow(Math.min(1, v), 0.50);
      const col = colorRamp(t);
      const k = 4 * (j * size + i);
      data[k] = col[0];
      data[k + 1] = col[1];
      data[k + 2] = col[2];
      data[k + 3] = Math.round(250 * Math.pow(t, 1.1));
    }
  }
  ctx.putImageData(img, 0, 0);
  tex.needsUpdate = true;
}

function cylinderBetween(a, b, r, color, opacity = 1) {
  const mid = new THREE.Vector3().addVectors(a, b).multiplyScalar(0.5);
  const len = a.distanceTo(b);
  const geom = new THREE.CylinderGeometry(r, r, len, 10);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), new THREE.Vector3().subVectors(b, a).normalize());
  scene.add(mesh);
  return mesh;
}

function makeConeAt(pos, dir, radius, height, color, opacity = 1) {
  const geom = new THREE.ConeGeometry(radius, height, 24);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: opacity < 1, opacity, depthWrite: opacity >= 1 });
  const cone = new THREE.Mesh(geom, mat);
  cone.position.copy(pos);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  scene.add(cone);
  return cone;
}

function lineLoop(points, color, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints([...points, points[0]]);
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const line = new THREE.Line(geom, mat);
  scene.add(line);
  return line;
}

