function updatePosterior(x, y) {
  const weights = [];
  let maxW = 0, sum = 0;
  for (let i = 0; i < posteriorDots.length; i++) {
    const z = zMin + (zMax - zMin) * i / (posteriorDots.length - 1);
    const w = gaussian2D(x, y, z) * prior(z);
    weights.push(w);
    maxW = Math.max(maxW, w);
    sum += w;
  }
  maxW = maxW || 1;
  for (let i = 0; i < posteriorDots.length; i++) {
    const t = Math.pow(weights[i] / maxW, 0.55);
    posteriorDots[i].scale.setScalar(0.45 + 2.2 * t);
    posteriorDots[i].material.opacity = 0.08 + 0.86 * t;
    posteriorDots[i].material.color.set(t > 0.45 ? cream : cyan);
  }
}
