  ];
  const s = steps[i] || steps[0];
  setLatentZ(s.z);
  if (s.sweep) startSweep();
  showPopup(s.popup[0], s.popup[1]);
}
window.goToStep = goToStep;
for (let i = 0; i < 4; i++) document.getElementById(`step${i}`).addEventListener('click', () => goToStep(i));

const _oldAnimateHook = { last: performance.now() };
function marginalizationTick() {
  requestAnimationFrame(marginalizationTick);
  if (!sweepAnimating) return;
  const elapsed = performance.now() - sweepStart;
  const progress = Math.min(1, elapsed / 3200);
  const z = zMin + (zMax - zMin) * progress;
  sweepPlane.position.z = z;
  updateTrace(z);
  if (performance.now() - _oldAnimateHook.last > 70 || progress >= 1) {
    drawMarginalTexture(progress);
    _oldAnimateHook.last = performance.now();
  }
