// joint-space cuboid → 12 thick brown CylinderGeometry edges
// conditional x1-x2 slices → three dark reddish-brown PlaneGeometry rectangles at fixed z
// conditional density glows → generated CanvasTexture heatmaps on transparent PlaneGeometry overlays
// decoder mean path in joint space → cyan TubeGeometry curve with dashed middle Line segment
// latent sample points → teal SphereGeometry markers with translucent cyan halo spheres
// path arrowhead → cyan ConeGeometry tangent to the joint-space curve
// marginal density panel → large right-side PlaneGeometry with generated marginal CanvasTexture
// marginal panel border → four black CylinderGeometry edges
// marginal mean path → cyan TubeGeometry curve on the right panel
// marginal sample points / draggable observation → teal SphereGeometry markers with cyan halo spheres
// marginal path arrowhead → cyan ConeGeometry tangent to the right-panel curve
// marginalization sweep plane → hidden translucent cyan PlaneGeometry animated through z
// projection sweep trace → hidden pale cyan Line from joint path to marginal panel during animation
// large marginalization arrow → pale gray CylinderGeometry shaft plus ConeGeometry head
// all visible math/caption text → addLabel HTML labels

const brown = 0x7a351e;
const darkBrown = 0x320900;
const cyan = 0x9fe2de;
const teal = 0x2d8f8a;
const cream = 0xffefbd;
const paleGray = 0xc7ced0;

scene.add(new THREE.AmbientLight(0xffffff, 1));

const xMin = -2.45, xMax = 2.45;
const yMin = -1.8, yMax = 1.8;
const zMin = -2.35, zMax = 2.35;

const rightPanel = {
  cx: 4.05,
  cy: -0.68,
  z: -1.28,
  w: 2.38,
  h: 3.35,
  xRange: [-2.45, 2.45],
  yRange: [-1.8, 1.8]
};

function mu(z) {
  return {
    x: 1.28 * Math.sin(1.05 * z) + 0.32 * z,
    y: -0.58 * z + 1.02 * Math.cos(0.92 * z)
  };
}

function prior(z) {
  return Math.exp(-0.5 * z * z / 1.35);
}

function gaussian2D(x, y, z) {
  const m = mu(z);
  const a = 0.72 * z + 0.25;
  const c = Math.cos(a), s = Math.sin(a);
  const dx = x - m.x, dy = y - m.y;
  const u = c * dx + s * dy;
  const v = -s * dx + c * dy;
  const s1 = 0.32;
  const s2 = 0.72;
  return Math.exp(-0.5 * ((u * u) / (s1 * s1) + (v * v) / (s2 * s2)));
}

function lerp(a, b, t) { return a + (b - a) * t; }

function colorRamp(t) {
  t = Math.max(0, Math.min(1, t));
  let c0, c1, u;
  if (t < 0.42) {
    c0 = [45, 8, 2];
    c1 = [154, 63, 44];
    u = t / 0.42;
  } else {
    c0 = [154, 63, 44];
    c1 = [255, 244, 192];
    u = (t - 0.42) / 0.58;
  }
  return [
    Math.round(lerp(c0[0], c1[0], u)),
    Math.round(lerp(c0[1], c1[1], u)),
    Math.round(lerp(c0[2], c1[2], u))
  ];
}

function makeConditionalTexture(z, opts = {}) {
  const size = opts.size || 180;
  const canvasTex = document.createElement('canvas');
  canvasTex.width = size;
  canvasTex.height = size;
  const ctx = canvasTex.getContext('2d');
  const img = ctx.createImageData(size, size);
  const data = img.data;
  for (let j = 0; j < size; j++) {
    const y = yMax - (j / (size - 1)) * (yMax - yMin);
    for (let i = 0; i < size; i++) {
      const x = xMin + (i / (size - 1)) * (xMax - xMin);
      const v = gaussian2D(x, y, z) * prior(z);
      const t = Math.pow(Math.min(1, v), 0.47);
      const col = colorRamp(t);
      const k = 4 * (j * size + i);
      data[k] = col[0];
      data[k + 1] = col[1];
      data[k + 2] = col[2];
      data[k + 3] = Math.round(252 * Math.pow(t, 1.05));
    }
  }
  ctx.putImageData(img, 0, 0);
  const tex = new THREE.CanvasTexture(canvasTex);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function cylinderBetween(a, b, r, color, opacity = 1, depthTest = true) {
  const mid = new THREE.Vector3().addVectors(a, b).multiplyScalar(0.5);
  const len = a.distanceTo(b);
  const geom = new THREE.CylinderGeometry(r, r, len, 12);
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthTest,
    depthWrite: opacity >= 1
  });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.position.copy(mid);
  mesh.quaternion.setFromUnitVectors(
    new THREE.Vector3(0, 1, 0),
    new THREE.Vector3().subVectors(b, a).normalize()
  );
  scene.add(mesh);
  return mesh;
}

function makeConeAt(pos, dir, radius, height, color, opacity = 1, depthTest = false) {
  const geom = new THREE.ConeGeometry(radius, height, 28);
  const mat = new THREE.MeshBasicMaterial({
    color,
    transparent: opacity < 1,
    opacity,
    depthTest,
    depthWrite: false
  });
  const cone = new THREE.Mesh(geom, mat);
  cone.position.copy(pos);
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  cone.renderOrder = 40;
  scene.add(cone);
  return cone;
}

function lineLoop(points, color, opacity = 1) {
  const geom = new THREE.BufferGeometry().setFromPoints([...points, points[0]]);
  const mat = new THREE.LineBasicMaterial({ color, transparent: opacity < 1, opacity });
  const line = new THREE.Line(geom, mat);
  scene.add(line);
  return line;
}

const edgePairs = [
  [[xMin, yMin, zMin], [xMax, yMin, zMin]], [[xMin, yMax, zMin], [xMax, yMax, zMin]],
  [[xMin, yMin, zMax], [xMax, yMin, zMax]], [[xMin, yMax, zMax], [xMax, yMax, zMax]],
  [[xMin, yMin, zMin], [xMin, yMax, zMin]], [[xMax, yMin, zMin], [xMax, yMax, zMin]],
  [[xMin, yMin, zMax], [xMin, yMax, zMax]], [[xMax, yMin, zMax], [xMax, yMax, zMax]],
  [[xMin, yMin, zMin], [xMin, yMin, zMax]], [[xMax, yMin, zMin], [xMax, yMin, zMax]],
  [[xMin, yMax, zMin], [xMin, yMax, zMax]], [[xMax, yMax, zMin], [xMax, yMax, zMax]]
];
edgePairs.forEach(([a, b]) => {
  const e = cylinderBetween(new THREE.Vector3(...a), new THREE.Vector3(...b), 0.018, brown);
  e.renderOrder = 7;
});

function addSlicePlane(z) {
  const base = new THREE.Mesh(
    new THREE.PlaneGeometry(xMax - xMin, yMax - yMin),
    new THREE.MeshBasicMaterial({
      color: darkBrown,
      transparent: true,
      opacity: 0.96,
      side: THREE.DoubleSide,
      depthWrite: true
    })
  );
  base.position.set(0, 0, z);
  base.renderOrder = 1;
  scene.add(base);

  const glow = new THREE.Mesh(
    new THREE.PlaneGeometry(xMax - xMin, yMax - yMin),
    new THREE.MeshBasicMaterial({
      map: makeConditionalTexture(z),
      transparent: true,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  glow.position.set(0, 0, z + 0.018);
  glow.renderOrder = 12;
  scene.add(glow);

  const pts = [
    new THREE.Vector3(xMin, yMin, z + 0.024),
    new THREE.Vector3(xMax, yMin, z + 0.024),
    new THREE.Vector3(xMax, yMax, z + 0.024),
    new THREE.Vector3(xMin, yMax, z + 0.024)
  ];
  const border = lineLoop(pts, brown, 0.9);
  border.renderOrder = 13;
  return { base, glow, border };
}

[-1.75, 0.05, 1.55].forEach(z => addSlicePlane(z));

function curvePoint(z) {
  const m = mu(z);
  return new THREE.Vector3(m.x, m.y, z);
}

function makeTubeForZRange(a, b, color, radius = 0.035) {
  const pts = [];
  const n = 84;
  for (let i = 0; i < n; i++) {
    const z = a + (b - a) * i / (n - 1);
    pts.push(curvePoint(z));
  }
  const curve = new THREE.CatmullRomCurve3(pts);
  const geom = new THREE.TubeGeometry(curve, 130, radius, 12, false);
  const mat = new THREE.MeshBasicMaterial({ color, depthTest: false, depthWrite: false });
  const mesh = new THREE.Mesh(geom, mat);
  mesh.renderOrder = 30;
  scene.add(mesh);
  return mesh;
}

makeTubeForZRange(zMin + 0.12, -0.34, cyan, 0.038);
makeTubeForZRange(0.42, zMax - 0.18, cyan, 0.038);

const dashedPts = [];
for (let i = 0; i < 56; i++) {
  dashedPts.push(curvePoint(-0.34 + 0.76 * i / 55));
}
const dashedLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints(dashedPts),
  new THREE.LineDashedMaterial({
    color: cyan,
    dashSize: 0.15,
    gapSize: 0.105,
    transparent: true,
    opacity: 1,
    depthTest: false
  })
);
dashedLine.computeLineDistances();
dashedLine.renderOrder = 31;
scene.add(dashedLine);

const jointArrowZ = zMax - 0.22;
const jointArrowP = curvePoint(jointArrowZ);
const jointTan = curvePoint(jointArrowZ).sub(curvePoint(jointArrowZ - 0.09)).normalize();
makeConeAt(jointArrowP.clone().add(jointTan.clone().multiplyScalar(0.11)), jointTan, 0.13, 0.33, cyan, 0.9);

function addTealSphere(pos, r = 0.078, draggable = false) {
  const outer = new THREE.Mesh(
    new THREE.SphereGeometry(r * 1.35, 28, 16),
    new THREE.MeshBasicMaterial({
      color: cyan,
      transparent: true,
      opacity: 0.72,
      depthTest: false,
      depthWrite: false
    })
  );
  outer.position.copy(pos);
  outer.renderOrder = 35;
  scene.add(outer);

  const inner = new THREE.Mesh(
    new THREE.SphereGeometry(r, 28, 16),
    new THREE.MeshBasicMaterial({ color: teal, depthTest: false, depthWrite: false })
  );
  inner.position.copy(pos);
  inner.renderOrder = 36;
  scene.add(inner);
  if (draggable) registerInteractive(inner, {
    title: 'Observed point x',
    body: 'This point lies in the marginal x-space after z has been integrated out.',
    tooltip: 'Drag observed x'
  });
  return { outer, inner };
}

const leftSample = addTealSphere(curvePoint(-1.75), 0.082);
const movingJointSample = addTealSphere(curvePoint(1.15), 0.082);

const marginalW = 150, marginalH = 210, zSamples = 130;
const zGrid = [];
for (let k = 0; k < zSamples; k++) zGrid.push(zMin + (zMax - zMin) * k / (zSamples - 1));

const marginalSlices = [];
const fullMarginal = new Float32Array(marginalW * marginalH);
let marginalMax = 0;

for (let k = 0; k < zSamples; k++) {
  const z = zGrid[k];
  const arr = new Float32Array(marginalW * marginalH);
  for (let j = 0; j < marginalH; j++) {
    const y = rightPanel.yRange[1] - (j / (marginalH - 1)) * (rightPanel.yRange[1] - rightPanel.yRange[0]);
    for (let i = 0; i < marginalW; i++) {
      const x = rightPanel.xRange[0] + (i / (marginalW - 1)) * (rightPanel.xRange[1] - rightPanel.xRange[0]);
      const val = gaussian2D(x, y, z) * prior(z);
      const idx = j * marginalW + i;
      arr[idx] = val;
      fullMarginal[idx] += val;
    }
  }
  marginalSlices.push(arr);
}
for (let i = 0; i < fullMarginal.length; i++) marginalMax = Math.max(marginalMax, fullMarginal[i]);

const marginalCanvas = document.createElement('canvas');
marginalCanvas.width = marginalW;
marginalCanvas.height = marginalH;
const marginalCtx = marginalCanvas.getContext('2d');
const marginalTex = new THREE.CanvasTexture(marginalCanvas);
marginalTex.colorSpace = THREE.SRGBColorSpace;

function drawMarginalTexture(progress = 1) {
  const img = marginalCtx.createImageData(marginalW, marginalH);
  const data = img.data;
  const upto = Math.max(1, Math.floor(progress * zSamples));
  for (let idx = 0; idx < marginalW * marginalH; idx++) {
    let sum = 0;
    for (let k = 0; k < upto; k++) sum += marginalSlices[k][idx];
    const t = Math.pow(Math.min(1, sum / marginalMax), 0.44);
    const col = colorRamp(t);
    const base = 4 * idx;
    data[base] = col[0];
    data[base + 1] = col[1];
    data[base + 2] = col[2];
    data[base + 3] = 255;
  }
  marginalCtx.putImageData(img, 0, 0);
  marginalTex.needsUpdate = true;
}
drawMarginalTexture(1);

const panelMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(rightPanel.w, rightPanel.h),
  new THREE.MeshBasicMaterial({ map: marginalTex, side: THREE.DoubleSide })
);
panelMesh.position.set(rightPanel.cx, rightPanel.cy, rightPanel.z);
panelMesh.renderOrder = 2;
scene.add(panelMesh);
registerInteractive(panelMesh, {
  title: 'Marginal density Pr(x | φ)',
  body: 'The right panel is obtained by summing the conditional x₁-x₂ slices over the latent coordinate z.',
  tooltip: 'Marginal density Pr(x | φ)'
});

function panelWorldFromData(x, y, zoff = 0.055) {
  const lx = (x - rightPanel.xRange[0]) / (rightPanel.xRange[1] - rightPanel.xRange[0]) * rightPanel.w - rightPanel.w / 2;
  const ly = (y - rightPanel.yRange[0]) / (rightPanel.yRange[1] - rightPanel.yRange[0]) * rightPanel.h - rightPanel.h / 2;
  return new THREE.Vector3(rightPanel.cx + lx, rightPanel.cy + ly, rightPanel.z + zoff);
}

function dataFromPanelLocal(local) {
  return {
    x: rightPanel.xRange[0] + ((local.x + rightPanel.w / 2) / rightPanel.w) * (rightPanel.xRange[1] - rightPanel.xRange[0]),
    y: rightPanel.yRange[0] + ((local.y + rightPanel.h / 2) / rightPanel.h) * (rightPanel.yRange[1] - rightPanel.yRange[0])
  };
}

const pb = rightPanel;
const bz = pb.z + 0.07;
[
  [new THREE.Vector3(pb.cx - pb.w / 2, pb.cy - pb.h / 2, bz), new THREE.Vector3(pb.cx + pb.w / 2, pb.cy - pb.h / 2, bz)],
  [new THREE.Vector3(pb.cx + pb.w / 2, pb.cy - pb.h / 2, bz), new THREE.Vector3(pb.cx + pb.w / 2, pb.cy + pb.h / 2, bz)],
  [new THREE.Vector3(pb.cx + pb.w / 2, pb.cy + pb.h / 2, bz), new THREE.Vector3(pb.cx - pb.w / 2, pb.cy + pb.h / 2, bz)],
  [new THREE.Vector3(pb.cx - pb.w / 2, pb.cy + pb.h / 2, bz), new THREE.Vector3(pb.cx - pb.w / 2, pb.cy - pb.h / 2, bz)]
].forEach(([a, b]) => {
  const m = cylinderBetween(a, b, 0.019, 0x000000, 1, true);
  m.renderOrder = 20;
});

const panelCurvePts = [];
for (let i = 0; i < 120; i++) {
  const z = zMin + 0.12 + (zMax - 0.3 - (zMin + 0.12)) * i / 119;
  const m = mu(z);
  panelCurvePts.push(panelWorldFromData(
    Math.max(rightPanel.xRange[0] + 0.04, Math.min(rightPanel.xRange[1] - 0.04, m.x)),
    Math.max(rightPanel.yRange[0] + 0.04, Math.min(rightPanel.yRange[1] - 0.04, m.y)),
    0.095
  ));
}
const panelCurve = new THREE.CatmullRomCurve3(panelCurvePts);
const panelCurveMesh = new THREE.Mesh(
  new THREE.TubeGeometry(panelCurve, 150, 0.019, 9, false),
  new THREE.MeshBasicMaterial({ color: cyan, transparent: true, opacity: 0.92, depthTest: false, depthWrite: false })
);
panelCurveMesh.renderOrder = 32;
scene.add(panelCurveMesh);

const panelEnd = panelCurvePts[panelCurvePts.length - 1];
const panelTan = panelEnd.clone().sub(panelCurvePts[panelCurvePts.length - 6]).normalize();
makeConeAt(panelEnd.clone().add(panelTan.clone().multiplyScalar(0.075)), panelTan, 0.085, 0.23, cyan, 0.9);

function addPanelPoint(x, y, draggable = false) {
  const p = addTealSphere(panelWorldFromData(x, y, draggable ? 0.14 : 0.125), draggable ? 0.057 : 0.052, draggable);
  return { outer: p.outer, inner: p.inner, data: { x, y }, draggable };
}

addPanelPoint(mu(-1.75).x, mu(-1.75).y, false);
const obs = addPanelPoint(mu(1.15).x, mu(1.15).y, true);

const sweepPlane = new THREE.Mesh(
  new THREE.PlaneGeometry(xMax - xMin, yMax - yMin),
  new THREE.MeshBasicMaterial({
    color: 0xdfffff,
    transparent: true,
    opacity: 0.28,
    side: THREE.DoubleSide,
    depthWrite: false,
    depthTest: false
  })
);
sweepPlane.position.set(0, 0, zMin);
sweepPlane.visible = false;
sweepPlane.renderOrder = 45;
scene.add(sweepPlane);

const traceGeom = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
const traceLine = new THREE.Line(
  traceGeom,
  new THREE.LineBasicMaterial({ color: cyan, transparent: true, opacity: 0.42, depthTest: false })
);
traceLine.visible = false;
traceLine.renderOrder = 46;
scene.add(traceLine);

const arrowStart = new THREE.Vector3(1.18, yMin - 0.58, -0.85);
const arrowEnd = new THREE.Vector3(3.42, yMin - 0.72, -1.08);
const arrowDir = new THREE.Vector3().subVectors(arrowEnd, arrowStart).normalize();
const arrowShaft = cylinderBetween(
  arrowStart,
  arrowEnd.clone().add(arrowDir.clone().multiplyScalar(-0.30)),
  0.045,
  paleGray,
  0.85,
  true
);
arrowShaft.renderOrder = 6;
makeConeAt(arrowEnd, arrowDir, 0.16, 0.42, paleGray, 0.85, true);

function updateTrace(z) {
  const m = mu(z);
  const p0 = new THREE.Vector3(m.x, m.y, z);
  const p1 = panelWorldFromData(
    Math.max(rightPanel.xRange[0], Math.min(rightPanel.xRange[1], m.x)),
    Math.max(rightPanel.yRange[0], Math.min(rightPanel.yRange[1], m.y)),
    0.15
  );
  traceGeom.setFromPoints([p0, p1]);
  traceGeom.attributes.position.needsUpdate = true;
}

function setLatentZ(z) {
  z = Math.max(zMin, Math.min(zMax, z));
  document.getElementById('latentZ').value = z.toFixed(2);
  document.getElementById('zReadout').textContent = `z = ${z.toFixed(2)}`;
  const p = curvePoint(z);
  movingJointSample.outer.position.copy(p);
  movingJointSample.inner.position.copy(p);
  updateTrace(z);
}

setLatentZ(1.15);

setCameraView({
  projection: 'orthographic',
  azimuthDeg: 56,
  elevationDeg: 19,
  rollDeg: 0,
  heightFraction: 0.92,
  target: [1.05, -0.18, -0.08],
  distanceScale: 1.15
});

const serif = 'font-family:Times New Roman,serif;font-style:italic;';
addLabel(`<span style="${serif}">x</span><sub>1</sub>`, new THREE.Vector3(-1.55, yMax + 0.42, zMin - 0.15), { fontSize: '32px', offset: [-4, -14] });
addLabel(`<span style="${serif}">x</span><sub>2</sub>`, new THREE.Vector3(xMin - 0.18, 0.25, zMin - 0.02), { fontSize: '32px', offset: [-28, 0] });
addLabel(`<span style="${serif}">z</span>`, new THREE.Vector3(-0.75, yMin - 0.16, zMin + 1.1), { fontSize: '30px', offset: [0, 18] });
addLabel(`Pr(<b>x</b>, <span style="${serif}">z</span> | &phi;)`, new THREE.Vector3(1.65, yMin - 0.24, zMax + 0.26), { fontSize: '31px', offset: [5, 22] });

addLabel(`<span style="${serif}">x</span><sub>1</sub>`, new THREE.Vector3(rightPanel.cx - 0.55, rightPanel.cy + rightPanel.h / 2 + 0.23, rightPanel.z), { fontSize: '31px', offset: [0, -8] });
addLabel(`<span style="${serif}">x</span><sub>2</sub>`, new THREE.Vector3(rightPanel.cx + rightPanel.w / 2 + 0.18, rightPanel.cy - rightPanel.h / 2 + 0.12, rightPanel.z), { fontSize: '29px', offset: [22, 8] });
addLabel(`Pr(<b>x</b>|&phi;)`, new THREE.Vector3(rightPanel.cx, rightPanel.cy - rightPanel.h / 2 - 0.25, rightPanel.z), { fontSize: '33px', offset: [8, 24] });

addLabel('Marginalize over<br>latent variable, <span style="font-family:Times New Roman,serif;font-style:italic;">z</span>', new THREE.Vector3(2.18, yMin - 0.72, -1.02), {
  fontSize: '26px',
  offset: [-14, 72],
  background: 'rgba(255,255,255,0.7)'
});

let sweepAnimating = false;
let sweepStart = 0;
let lastMarginalDraw = 0;

function startSweep() {
  sweepAnimating = true;
  sweepStart = performance.now();
  lastMarginalDraw = 0;
  sweepPlane.visible = true;
  traceLine.visible = true;
  drawMarginalTexture(0.02);
}

document.getElementById('btnSweep').addEventListener('click', startSweep);
document.getElementById('latentZ').addEventListener('input', e => setLatentZ(parseFloat(e.target.value)));

let draggingObs = false;
const dragRaycaster = new THREE.Raycaster();
const dragPointer = new THREE.Vector2();

function pointerToNdc(event) {
  const rect = canvas.getBoundingClientRect();
  dragPointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  dragPointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
}

function dragObservation(event) {
  pointerToNdc(event);
  dragRaycaster.setFromCamera(dragPointer, camera);
  const hit = dragRaycaster.intersectObject(panelMesh, false)[0];
  if (!hit) return;
  const local = panelMesh.worldToLocal(hit.point.clone());
  local.x = Math.max(-rightPanel.w / 2, Math.min(rightPanel.w / 2, local.x));
  local.y = Math.max(-rightPanel.h / 2, Math.min(rightPanel.h / 2, local.y));
  const data = dataFromPanelLocal(local);
  obs.data = data;
  const p = panelWorldFromData(data.x, data.y, 0.14);
  obs.outer.position.copy(p);
  obs.inner.position.copy(p);
}

canvas.addEventListener('pointerdown', event => {
  pointerToNdc(event);
  dragRaycaster.setFromCamera(dragPointer, camera);
  const hitObs = dragRaycaster.intersectObject(obs.inner, false)[0];
  if (hitObs) {
    draggingObs = true;
    controls.enabled = false;
    dragObservation(event);
  }
});

window.addEventListener('pointermove', event => {
  if (draggingObs) dragObservation(event);
});

window.addEventListener('pointerup', () => {
  if (draggingObs) {
    draggingObs = false;
    controls.enabled = true;
  }
});

function goToStep(i) {
  const steps = [
    {
      z: 1.15,
      sweep: false,
      popup: ['Joint latent-variable model', 'The large cuboid is Pr(x, z | φ). Each dark vertical sheet is an x₁-x₂ conditional density at a different latent coordinate z.']
    },
    {
      z: -1.75,
      sweep: false,
      popup: ['Move along z', 'Changing z moves along the cyan decoder mean curve and selects a different bright density region on the corresponding slice.']
    },
    {
      z: 1.15,
      sweep: true,
      popup: ['Marginalize over z', 'The animation sweeps through latent z and accumulates the conditional slices into the right-hand marginal density Pr(x | φ).']
    },
    {
      z: 1.15,
      sweep: false,
      popup: ['Joint versus marginal', 'The right panel keeps only the observable variables x₁ and x₂. The latent coordinate z has been summed out, leaving the banana-shaped marginal density.']
    }
  ];
  const s = steps[i] || steps[0];
  setLatentZ(s.z);
  if (s.sweep) startSweep();
  else drawMarginalTexture(1);
  showPopup(s.popup[0], s.popup[1]);
}

for (let i = 0; i < 4; i++) {
  document.getElementById(`step${i}`).addEventListener('click', () => goToStep(i));
}

function marginalizationTick() {
  requestAnimationFrame(marginalizationTick);
  if (!sweepAnimating) return;
  const elapsed = performance.now() - sweepStart;
  const progress = Math.min(1, elapsed / 3100);
  const z = zMin + (zMax - zMin) * progress;
  sweepPlane.position.z = z;
  setLatentZ(z);
  if (performance.now() - lastMarginalDraw > 65 || progress >= 1) {
    drawMarginalTexture(progress);
    lastMarginalDraw = performance.now();
  }
  if (progress >= 1) {
    sweepAnimating = false;
    setLatentZ(1.15);
    setTimeout(() => {
      sweepPlane.visible = false;
      traceLine.visible = false;
    }, 420);
  }
}
marginalizationTick();
